function sanitizeTelemetry(payload) {
  const sensitiveKeys = ['token', 'password', 'apiKey', 'creditCard', 'phone'];
  return JSON.parse(JSON.stringify(payload, (key, value) => 
    sensitiveKeys.includes(key) ? '***REDACTED***' : value
  ));
}

async function resilientFetch(fn, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxRetries - 1) throw err;
      await new Promise(r => setTimeout(r, 2 ** attempt * 1000 + Math.random() * 200));
    }
  }
}
